    stk asegs m lo spf -> aceil <= lo -> lo <= spf - AFREE_STACK ->
    rw_cells asegs m (errno_addr x4) [C4 errv] -> mem_inv asegs m -> x4 = Z_to_bv 64 ATP ->
    spf mod 16 = 0 -> 2 ^ 45 <= spf <= 2 ^ 47 -> ACONST m ->
    (bv_unsigned x8 <= aceil \/ bv_unsigned x8 mod 8 <> 0) ->
    trace_ok (as_TR H) APC0_FREE [NT_DRET1] ->
    (match ns with [] => True | (q', _) :: _ => 0x6e8000 <= q' < 2 ^ 47 end) ->
    (forall (msF' : machine_state) (mo' : Model) (m' : mem) (s' : as_St H) (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
       as_VIS H s' msF' = MS (mkR (Z_to_bv 64 NT_DRET1) (Z_to_bv 64 spf) x3 x4 t0 t1 t2 x8 x9
                                 (Z_to_bv 64 (match ns with [] => 0 | (q', _) :: _ => q' end)) a1 a2 a3 a4 a5 a6 a7 x18 x19 x20
                                 x21 (Z_to_bv 64 0x7fff8000) x23 x24
                                 x25 (Z_to_bv 64 (match ns with [] => 0 | (q', _) :: _ => q' end)) x27 t3 t4 t5 t6)
                             F (Z_to_bv 64 (match ns with [] => NT_L2 | _ => NT_LOOP end)) fc None m' (seg_rom asegs) ->
       as_AKREL H s' (mkCfg msF' mo') -> as_MPRES H mo mo' ->
       mem_inv asegs m' -> stk asegs m' lo spf -> rw_cells asegs m' (errno_addr x4) [C4 errv] -> as_rauxv_ok H m' B ->
       apres H (as_lb_remove H id LB) spf m m' -> as_RHEAP H s' (as_lb_remove H id LB) m' -> ACONST m' ->
       as_AL H s' >= as_AL H s - as_Cf H 32 ->
       as_SR H Q (mkCfg msF' mo')) ->
    as_SR H Q (mkCfg msF mo).
Proof.
    intros Q x1 x3 x4 x5 x6 x7 x8 x9 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x26 x25 x27 x28 x29 x30 x31
      F fc msF m s LB q tl ns spf lo B errv mo id VIS HIN CQ ADQ RH KR CF RA SPB ST CE LO ERR MI TP SP16 SPR AC S0LOW TRK NXR K.
    set (nxt := match ns with [] => 0 | (q', _) :: _ => q' end) in *.
    pose proof (aceil_facts) as ACF. destruct ACF as ((ACF1 & ACF2) & ACF3 & ACF4).
    pose proof (ah_blocks H HH _ _ _ (id, q, 32) RH HIN) as (Q0 & Q16 & Qn & QI & QC & QF & QAPP).
    unfold blk_addr, blk_size in Q0, Q16, Qn, QI, QC, QF, QAPP. cbn [fst snd] in Q0, Q16, Qn, QI, QC, QF, QAPP.
    assert (GZQ : gz m q 32) by (intros i Hi; eapply sh0_of_addressable; [exact ADQ | change (8 * (32 / 8)) with 32; lia]).
    remember (mkR x1 (Z_to_bv 64 spf) x3 x4 x5 x6 x7 x8 x9 (Z_to_bv 64 q) x11 x12 x13 x14 x15 x16 x17 x18 x19 x20
                  x21 (Z_to_bv 64 0x7fff8000) x23 x24 x25 x26 x27 x28 x29 x30 x31) as R eqn:HR0.

    pose (E := Eseed R [Z_to_bv 64 q; Z_to_bv 64 spf; Z_to_bv 64 nxt]).
    assert (HR : regs_ok E (srs sr_id [(10%bv, EVar 32); (2%bv, EVar 33); (22%bv, ELit 0x7fff8000)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
    assert (HK : know_ok asegs E m
       (kn_fix 20 [AOPDEL2] (SCR [] [] []) NT_LOOP (srs sr_id [(10%bv, EVar 32); (2%bv, EVar 33); (22%bv, ELit 0x7fff8000)])
         [ KWord (SA (EVar 32) 0) 8 (EVar 34);
           KRange (EVar 33) (2 ^ 45) (2 ^ 47); KRange (EVar 32) 0x6e8000 (2 ^ 47); KAlign (EVar 32) 8 ] 40)).
    { kn_eval. unfold know_ok.
      apply Forall_cons.
      { eapply (kword_of_rw_cells asegs E m q _ 0%nat (C8 (Z_to_bv 64 nxt))); [exact CQ | reflexivity | reflexivity | lia
          | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off Z.of_nat]; lia | cbn; lia | cbn; lia | reflexivity]. }
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. lia. }
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. unfold AIMG_TOP in QI. lia. }
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. split; [lia|].
        destruct (proj1 (Z.mod_divide q 16 ltac:(discriminate)) Q16) as [k8 Hk8].
        apply (proj2 (Z.mod_divide q 8 ltac:(discriminate))). exists (2 * k8). rewrite Hk8. ring. }
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R NT_LOOP m (seg_rom asegs) HR HK 40%nat [AOPDEL2] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1; try sc_shdj; try sc_dj. }
    rreg HR' 1%bv G1. rreg HR' 2%bv G2. rreg HR' 22%bv G22. rreg HR' 10%bv G10. rreg HR' 11%bv G11. rreg HR' 26%bv G26.
    assert (GK : forall r x, In r [3; 4; 8; 9; 18; 19; 20; 21; 23; 24; 25; 27]%bv -> getr R r = x -> getr R' r = x).
    { intros r x Hr Hx. rewrite <- Hx.
      eapply (syms_id_sound R _ _ R' [3; 4; 8; 9; 18; 19; 20; 21; 23; 24; 25; 27]%bv HR'); [vm_cast_no_check (@eq_refl bool true) | exact Hr]. }
    assert (G4 : getr R' 4 = x4) by (apply GK; [inb | subst R; reflexivity]).
    assert (G8 : getr R' 8 = x8) by (apply GK; [inb | subst R; reflexivity]).
    eapply (sr_blk H HH); [exact KR | exact VIS | rewrite HR0; apply rfull_mkR | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1.

    eapply (ah_seq H HH).
    { eapply (ah_opdel2 H HH) with (p := id) (A := q) (n := 32) (LB := LB) (lo := lo) (B := B) (errv := errv) (CH := [])
        (sbs := shadow_of 32);
        [ exact VIS1 | exact RH | exact KR1 | exact HIN | exact CF | exact (rw_cells_to_CB m q _ CQ) | exact (proj2 ADQ) | reflexivity
        | exact RA | rewrite G2, u64_of_Z by lia; lia | rewrite G2, u64_of_Z by lia; exact ST | exact CE | rewrite G2, u64_of_Z by lia; exact LO
        | rewrite G4; exact ERR | exact MI | rewrite G4; exact TP | rewrite G2, u64_of_Z by lia; exact SP16 | exact AC
        | rewrite G8; apply (ah_chain_nil H HH); exact S0LOW
        | rewrite G1; cbn [map]; rewrite u64_of_Z by (unfold NT_DRET1; lia); exact TRK
        | exact G10 ]. }
    intros c2 POST. destruct c2 as [msF2 mo2].
    destruct POST as (t0' & t1' & t2' & a0' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m2 & s'
                      & VIS2 & KR2 & MP2 & MI2 & ST2 & ERR2 & RA2 & AP2 & RH2 & AC2 & AL2).
    cbn [cfg_ms cfg_model] in VIS2, KR2, MP2.
    rewrite G1, (ret_pc_even 970784 ltac:(lia) eq_refl) in VIS2.
    rewrite G2, u64_of_Z in ST2, AP2 by lia. rewrite G4 in ERR2.

    lazymatch type of VIS2 with _ = MS ?T _ _ _ _ _ _ => remember T as R2 eqn:HR2 end.
    pose (E2 := Eseed R2 [Z_to_bv 64 nxt]).
    assert (HRb : regs_ok E2 (srs sr_id [(26%bv, EVar 32)]) R2).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R2; evs; exact G26. }
    destruct ns as [|[q' tl'] ns'].
    -
      assert (HKb : know_ok asegs E2 m2 [KRange (EVar 32) 0 0]).
      { unfold know_ok. apply Forall_cons; [|apply Forall_nil]. cbn [kentry_ok]. evs. subst nxt. rewrite u64_of_Z by lia. lia. }
      xrun_at (PropExec.mkFP F fc) asegs R2 970784 m2 (seg_rom asegs) HRb HKb 10%nat [NT_LOOP; NT_L2] (SCR [] [] []) 40%N.
      { split_scs; try sc_auto1. }
      assert (HF2 : rfull R2) by (rewrite HR2; apply rfull_mkR).
      pose proof (msteps_full asegs _ _ Hms0 HF2) as HF3. cbn [ms_regs] in HF3.
      readback HR'0 HF3 HR2 HRe3.
      rreg HR'0 10%bv J10. rreg HR'0 26%bv J26.
      rewrite ?J10, ?J26, ?G1, ?G2, ?G4, ?G8, ?G26,
        ?(GK 3%bv x3 ltac:(inb) ltac:(subst R; reflexivity)), ?(GK 9%bv x9 ltac:(inb) ltac:(subst R; reflexivity)),
        ?(GK 18%bv x18 ltac:(inb) ltac:(subst R; reflexivity)), ?(GK 19%bv x19 ltac:(inb) ltac:(subst R; reflexivity)),
        ?(GK 20%bv x20 ltac:(inb) ltac:(subst R; reflexivity)), ?(GK 21%bv x21 ltac:(inb) ltac:(subst R; reflexivity)),
        ?G22, ?(GK 23%bv x23 ltac:(inb) ltac:(subst R; reflexivity)),
        ?(GK 24%bv x24 ltac:(inb) ltac:(subst R; reflexivity)), ?(GK 25%bv x25 ltac:(inb) ltac:(subst R; reflexivity)),
        ?(GK 27%bv x27 ltac:(inb) ltac:(subst R; reflexivity)) in HRe3.
      eapply (sr_blk H HH); [exact KR2 | exact VIS2 | rewrite HR2; apply rfull_mkR | exact Hms0 |].
      intros msF3 mo3 KR3 MP3 VIS3.
      apply (K msF3 mo3 m2 s' t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6'); try assumption.
      + rewrite VIS3, HRe3. reflexivity.
      + eapply (ah_mpres_trans H HH); [exact MP1 | eapply (ah_mpres_trans H HH); [exact MP2 | exact MP3]].
    -
      assert (HKb : know_ok asegs E2 m2 [KRange (EVar 32) 0x6e8000 (2 ^ 47)]).
      { unfold know_ok. apply Forall_cons; [|apply Forall_nil]. cbn [kentry_ok]. evs. subst nxt. rewrite u64_of_Z by lia. lia. }
      xrun_at (PropExec.mkFP F fc) asegs R2 970784 m2 (seg_rom asegs) HRb HKb 10%nat [NT_LOOP; NT_L2] (SCR [] [] []) 40%N.
      { split_scs; try sc_auto1. }
      assert (HF2 : rfull R2) by (rewrite HR2; apply rfull_mkR).
      pose proof (msteps_full asegs _ _ Hms0 HF2) as HF3. cbn [ms_regs] in HF3.
      readback HR'0 HF3 HR2 HRe3.
      rreg HR'0 10%bv J10. rreg HR'0 26%bv J26.
      rewrite ?J10, ?J26, ?G1, ?G2, ?G4, ?G8, ?G26,
        ?(GK 3%bv x3 ltac:(inb) ltac:(subst R; reflexivity)), ?(GK 9%bv x9 ltac:(inb) ltac:(subst R; reflexivity)),
        ?(GK 18%bv x18 ltac:(inb) ltac:(subst R; reflexivity)), ?(GK 19%bv x19 ltac:(inb) ltac:(subst R; reflexivity)),
        ?(GK 20%bv x20 ltac:(inb) ltac:(subst R; reflexivity)), ?(GK 21%bv x21 ltac:(inb) ltac:(subst R; reflexivity)),
        ?G22, ?(GK 23%bv x23 ltac:(inb) ltac:(subst R; reflexivity)),
        ?(GK 24%bv x24 ltac:(inb) ltac:(subst R; reflexivity)), ?(GK 25%bv x25 ltac:(inb) ltac:(subst R; reflexivity)),
        ?(GK 27%bv x27 ltac:(inb) ltac:(subst R; reflexivity)) in HRe3.
      eapply (sr_blk H HH); [exact KR2 | exact VIS2 | rewrite HR2; apply rfull_mkR | exact Hms0 |].
      intros msF3 mo3 KR3 MP3 VIS3.
      apply (K msF3 mo3 m2 s' t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6'); try assumption.
      + rewrite VIS3, HRe3. reflexivity.
      + eapply (ah_mpres_trans H HH); [exact MP1 | eapply (ah_mpres_trans H HH); [exact MP2 | exact MP3]].
Qed.

End NtLoop.
Section StNT.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis HCF : forall n, as_Cf H n = 0.

  Variables (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (fc : bv 32).
  Variables (st1 st2 o1 o2 spz lo B shi : Z) (errv : word) (LF : list fframe) (LB0 : list block) (m0 : mem) (mo0 : Model) (st0 : as_St H).
  Hypothesis SPZ16 : spz mod 16 = 0.
  Hypothesis SPZR : 2 ^ 45 <= spz - 96 /\ spz <= 2 ^ 47.
  Hypothesis LOH : aceil <= lo /\ lo <= spz - 96 - AFREE_STACK.
  Hypothesis O1R : AIMG_TOP <= o1 /\ o1 + 40 <= aceil /\ o1 mod 8 = 0 /\ in_app_mem o1 (o1 + 40).
  Hypothesis O2R : AIMG_TOP <= o2 /\ o2 + 40 <= 2 ^ 47 /\ o2 mod 8 = 0 /\ in_app_mem o2 (o2 + 40) /\ (o2 + 40 <= aceil \/ spz <= o2).
  Hypothesis AP12 : apart o1 40 o2 40.
  Hypothesis O1E : o1 = st1 + 88.
  Hypothesis O2E : o2 = st2 + 88.
  Hypothesis TPV : tp = Z_to_bv 64 ATP.

  Hypothesis FS1 : as_FSB H <= o1 /\ o1 + 40 <= as_FSB H + AFS_SIZE.
  Hypothesis FS2 : (as_FSB H <= o2 /\ o2 + 40 <= as_FSB H + AFS_SIZE) \/ aceil <= o2.
  Hypothesis AFS1 : afs_write_ok H LF (o1, o1 + 40).
  Hypothesis AFS2 : afs_write_ok H LF (o2, o2 + 40).
  Hypothesis ACO1 : aconst_ok (o1, o1 + 40).
  Hypothesis ACO2 : aconst_ok (o2, o2 + 40).
  Hypothesis AL0 : 0 <= as_AL H st0.
  Hypothesis SPB : spz <= B.
  Hypothesis TRK2 : trace_ok (as_TR H) APC0_FREE [NT_DRET2].
  Hypothesis TRK1 : trace_ok (as_TR H) APC0_FREE [NT_DRET1].

  Hypothesis SV2H : (exists f, In f LF /\ ff_addr f <= o2 /\ o2 + 40 <= ff_addr f + fsz (ff_class f)) \/ (lo + 64 <= o2 /\ o2 + 104 <= shi).

  Definition XON : list (Z * Z) := [(o1, o1 + 40); (o2, o2 + 40)].

  Definition TSN (s : as_St H) (LB : list block) (bl2 bc2 : Z) (ents2 : list (Z * (Z * (Z * Z * Z)))) (LBs2 : list block) (m : mem) : Prop :=
    mem_inv asegs m /\ stk asegs m lo spz /\ rw_cells asegs m (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m B
    /\ ACONST m /\ as_RFS H LF m /\ stack0 m lo shi /\ as_RHEAP H s LB m
    /\ sto_frame m (spz - 96) ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10
    /\ addressable m o1 40 /\ addressable m o2 40 /\ umap_sh m 32 (bl2, bc2, ents2)
    /\ xpres H (LB0 ++ LBs2) spz XON m0 m
    /\ lb_own LB m.

  Definition wTN (iv : Z * Z) : Prop :=
    (o1 <= fst iv /\ snd iv <= o1 + 40) \/ (o2 <= fst iv /\ snd iv <= o2 + 40) \/ (lo <= fst iv /\ snd iv <= spz - 96).

  Lemma TSN_munch : forall s LB bl2 bc2 ents2 LBs2 m m' W,
    TSN s LB bl2 bc2 ents2 LBs2 m -> munch W m m' -> wmono asegs m m' -> mem_inv asegs m' -> Forall wTN W ->
    (forall b, In b (LB0 ++ LBs2) -> In b LB) ->
    (bc2 <> 0 -> bl2 + 8 * bc2 <= 2 ^ 47) -> (forall p k v, In (p, (k, v)) ents2 -> p + 32 <= 2 ^ 47) ->
    (bc2 <> 0 -> 0 <= bl2) -> (forall p k v, In (p, (k, v)) ents2 -> 0 <= p) -> 0 <= bc2 ->
    TSN s LB bl2 bc2 ents2 LBs2 m'.
