  Definition ntm_post (bl2 bc2 : Z) (ents2 : list (Z * (Z * (Z * Z * Z)))) (LBs2 : list block) : config -> Prop :=
    fun cf => exists x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 m'
                     (s' : as_St H) (LB' : list block) (F' : bvmap 5 word),
