                                        x14 x15 x16 x17 x18 x19 x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
                                   F' (Z_to_bv 64 NT_END) fc None m' (seg_rom asegs)
      /\ as_AKREL H s' cf /\ as_MPRES H mo0 (cfg_model cf)
      /\ mem_inv asegs m' /\ stk asegs m' lo spz /\ rw_cells asegs m' (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m' B
      /\ as_RHEAP H s' LB' m' /\ Permutation LB' (LB0 ++ LBs2)
      /\ umapx MI_A 32 (nval32 ASEGS) (lbl LB') m' o1 bl2 bc2 ents2 /\ umap_sh m' 32 (bl2, bc2, ents2)
      /\ umapx MI_A 32 (nval32 ASEGS) (lbl LB') m' o2 0 0 []
      /\ addressable m' o1 40 /\ addressable m' o2 40
      /\ sto_frame m' (spz - 96) ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10
      /\ xpres H LB0 spz [(o1, o1 + 40); (o2, o2 + 40)] m0 m'
      /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi
      /\ as_AL H s' >= as_AL H st0
      /\ lb_own LB' m'.

