  Definition ntt2_srC2 : list expr := srs sr_id
    [(2%bv, EVar 34); (10%bv, EAlu ALU_ADD (EVar 33) (ELit 16)); (12%bv, EVar 36); (18%bv, EAlu ALU_ADD (EVar 32) (ELit 16));
     (19%bv, EVar 32); (22%bv, ELit SHBASE); (24%bv, shE (EVar 32))].
  Definition ntt2_KC2 : list kentry :=
    [ KRange (EVar 32) AIMG_TOP (2 ^ 47); KAlign (EVar 32) 8; KRange (EVar 33) AIMG_TOP (2 ^ 47); KAlign (EVar 33) 8;
      KDisj (SA (EVar 32) 0) (ELit 40) (SA (EVar 33) 0) (ELit 40);
      KWord (SA (EVar 32) 0) 8 (EVar 35); KRange (EVar 35) AIMG_TOP (2 ^ 47); KAlign (EVar 35) 16;
      KWr (SA (EVar 35) 0) (EVar 37); KRange (EVar 36) 0 (2 ^ 31); KRange (EVar 37) 16 (2 ^ 35);
      KDisj (SA (EVar 32) 0) (ELit 40) (SA (EVar 35) 0) (EVar 37); KDisj (SA (EVar 33) 0) (ELit 40) (SA (EVar 35) 0) (EVar 37) ].

  Lemma ntt2_u_bnds : forall LBs2 bl2 bc2 ents2, umapx MI_A 32 (nval32 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ents2 ->
    (bc2 <> 0 -> bl2 + 8 * bc2 <= 2 ^ 47) /\ (forall p k v, In (p, (k, v)) ents2 -> p + 32 <= 2 ^ 47) /\
    (bc2 <> 0 -> 0 <= bl2) /\ (forall p k v, In (p, (k, v)) ents2 -> 0 <= p) /\ 0 <= bc2.
  Proof.
    intros LBs2 bl2 bc2 ents2 U.
    split; [intros _; exact (u_bl_hi U)|].
    split; [intros p k v Hi; destruct (u_node U p k v Hi) as (_ & _ & Hp & _); exact Hp|].
    split; [intros Hbc; pose proof (u_bl_lo U Hbc); lia|].
    split; [intros p k v Hi; destruct (u_node U p k v Hi) as (_ & Hp & _); lia|].
    pose proof (BSEQ_boundT bc2 (u_bseq U)); lia.
  Qed.

  Lemma ntt2_sc_so : forall E M (sa : saddr) (A N a : Z) (k : nat),
    wr_at asegs M A N -> adenot E sa = Z_to_bv 64 a -> A <= a -> a + Z.of_nat k <= A + N ->
    sc_denot asegs M E (SCStoreOk sa k).
  Proof.
    intros E M sa A N a k W Ha H1 H2. cbn [sc_denot]. rewrite Ha.
    pose proof W as (W0 & W1 & _).
    replace a with (A + (a - A)) by lia. apply (wr_at_store_ok asegs M A N (a - A) k W); lia.
  Qed.

  Ltac ntt2_dj := cbn [disjoint_from cells_size csize app]; lia.

  Lemma ntt2_outside_app : forall W1 W2 x, outside (W1 ++ W2) x -> outside W1 x /\ outside W2 x.
  Proof.
    induction W1 as [|[l h] W1 IH]; intros W2 x Hx; cbn [app outside] in *; [split; [exact I | exact Hx]|].
    destruct Hx as [X1 X2]. destruct (IH W2 x X2) as [Y1 Y2]. split; [split; [exact X1 | exact Y1] | exact Y2].
  Qed.

  Lemma ntt2_munch_app : forall W1 W2 m m1 m2, munch W1 m m1 -> munch W2 m1 m2 -> munch (W1 ++ W2) m m2.
  Proof.
    intros W1 W2 m m1 m2 M1 M2 x Hx. destruct (ntt2_outside_app W1 W2 _ Hx) as [Y1 Y2].
    rewrite (M2 x Y2). exact (M1 x Y1).
  Qed.

  Lemma ntt2_wmono_trans : forall m1 m2 m3, wmono asegs m1 m2 -> wmono asegs m2 m3 -> wmono asegs m1 m3.
  Proof. intros m1 m2 m3 Y1 Y2 x Hx. apply Y2, Y1, Hx. Qed.

  Lemma ntt2_agree_munch : forall W (ma m m' : mem) a n, HRepFacts.agree_on ma m a n -> munch W m m' ->
    disjoint_from W a n -> 0 <= a -> a + n <= 2 ^ 64 -> HRepFacts.agree_on ma m' a n.
  Proof.
    intros W ma m m' a n AG MU D Ha Hn i Hi. rewrite (MU (Z_to_bv 64 (a + i))); [apply AG; exact Hi|].
    rewrite u64_of_Z by lia. eapply disjoint_outside; [exact D | lia].
  Qed.

  Lemma ntt2_afs_sub : forall a b a' b', afs_write_ok H LF (a, b) -> a <= a' -> b' <= b -> afs_write_ok H LF (a', b').
  Proof.
    intros a b a' b' HW H1 H2. unfold afs_write_ok in *. cbn [fst snd] in *.
    destruct HW as [[X Y] | (f & Hf & F1 & F2)]; [left; split; lia | right; exists f; split; [exact Hf | lia]].
  Qed.

  Lemma ntt2_dsh : forall A n lo' hi', 0 <= A -> 0 <= n -> A + n <= AAPP_HI -> in_app_mem lo' hi' ->
    sh A + nsh n <= lo' \/ hi' <= sh A.
  Proof.
    intros A n lo' hi' HA Hn HAn HI. pose proof (sh_nsh_high A n HA Hn HAn) as S.
    assert (0 <= A / 8) by (apply Z.div_pos; lia). unfold in_app_mem in HI. unfold sh in *. lia.
  Qed.

  Lemma ntt2_node_blk : forall (LBa LBb : list block) bl bc (ents : list (Z * (Z * (Z * Z * Z)))) p0 k0 v0,
    Permutation LBa (LB0 ++ LBb) -> Permutation (lbl LBb) (umap_blocks 32 bl bc ents) -> In (p0, (k0, v0)) ents ->
