    getr R3 19 = Z_to_bv 64 o1 -> getr R3 22 = Z_to_bv 64 2147450880 -> getr R3 24 = rSh (Z_to_bv 64 o1) -> getr R3 27 = s11 ->
    TSN s LB bl2 bc2 ((p, (k, v)) :: ents2') LBs2 m3 -> Permutation LB (LB0 ++ LBs2) -> as_AL H s >= as_AL H st0 ->
