    pose proof (ah_blocks H HH _ _ _ _ RH HqL) as (B0' & B16' & Bn' & BI' & BC' & BF' & BA').
    unfold blk_addr, blk_size in B0', B16', Bn', BI', BC', BF', BA'. cbn [Datatypes.fst Datatypes.snd] in B0', B16', Bn', BI', BC', BF', BA'.
    pose proof (AP2 _ Hq0) as NA0. unfold apart, blk_addr, blk_size in NA0. cbn [Datatypes.fst Datatypes.snd] in NA0.
    unfold apart in NA1. specialize (NA2 BC0). unfold apart in NA2.
    eapply (ntt2_agree_munch _ m0 m3 m'); [| exact MUT | ntt2_dj | lia | lia].
    eapply (agree_of_xpres H (LB0 ++ LBs2) spz XON m0 m3 p0 32 XP); [| lia | lia].
    intros i Hi. split.
    + right; right; left. exists (q0, p0, 32). split; [apply in_or_app; right; exact Hq0 | unfold blk_addr, blk_size; cbn [Datatypes.fst Datatypes.snd]; lia].
    + unfold XON. cbn [rin_ivs Datatypes.fst Datatypes.snd]. lia.
  - intros i Hi Hne. destruct Hne as [Hne | Hne]; [discriminate Hne |]. cbn [hdkey] in Hne.
    eapply (ntt2_agree_munch _ m0 m3 m'); [| exact MUT | ntt2_dj | lia | lia].
    eapply (agree_of_xpres H (LB0 ++ LBs2) spz XON m0 m3 (bl2 + 8 * i) 8 XP); [| lia | lia].
    intros j Hj. split.
    + right; right; left. exists (qb, bl2, 8 * bc2). split; [apply in_or_app; right; exact INqb | unfold blk_addr, blk_size; cbn [Datatypes.fst Datatypes.snd]; lia].
    + unfold XON. cbn [rin_ivs Datatypes.fst Datatypes.snd]. lia.
  - intros _. cbn [hdkey]. eapply cellw8_of_rw_cells; [exact CSL' | lia | lia].
  - exact AP2.
  - unfold umap_sh. split.
    + intros _. change (addressable m' bl2 (8 * bc2)).
      eapply addressable_transport; [exact (proj1 USH BC0) | exact MUT | exact WMT | apply DSH; lia].
    + intros p0 k0 v0 Hin. change (In (p0, (k0, v0)) ((p, (k, v)) :: ents2')) in Hin.
      pose proof (u_node U2 p0 k0 v0 Hin) as (_ & N0 & N1 & _).
      eapply addressable_transport; [exact (proj2 USH p0 k0 v0 Hin) | exact MUT | exact WMT | apply DSH; lia].
  - eapply (xpres_munch_mixed H HH s LB LB0 LBs2 spz XON _ m0 m3 m'); [ | exact RH | exact PE | lia | exact MUT | exact WMT | ].
    + eapply (xpres_weaken H); [exact XP | lia | intros b Hb; apply in_or_app; left; exact Hb | intros a Ha; exact Ha].
    + apply Forall_cons; [|apply Forall_cons; [|apply Forall_cons; [|apply Forall_nil]]]; unfold wmix; cbn [Datatypes.fst Datatypes.snd].
      * right; right. exists qb, bl2, (8 * bc2). split; [exact INqb | lia].
      * right; left. intros a Ha. unfold XON. cbn [rin_ivs Datatypes.fst Datatypes.snd]. right; left. lia.
      * left. lia.
  - exact (lb_own_wmono _ _ _ OWN WMT).
Qed.

