  rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 10%bv G10. rreg HR' 11%bv G11. rreg HR' 12%bv G12.
  rreg HR' 13%bv G13. rreg HR' 14%bv G14. rreg HR' 18%bv G18. rreg HR' 19%bv G19.
  rreg HR' 20%bv G20. rreg HR' 21%bv G21. rreg HR' 22%bv G22. rreg HR' 23%bv G23. rreg HR' 24%bv G24.
  repeat first [rewrite w_addm in G10 by lia | rewrite w_add in G10 by lia]. repeat first [rewrite w_addm in G11 by lia | rewrite w_add in G11 by lia].
  assert (RD : PropExec.rdn asegs M1 (Z_to_bv 64 (o2 + 32)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 mlfz)))
    by exact (proj2 (cellw4_of_rw_cells _ _ _ Q32M MLFR ltac:(lia))).
  assert (A10 : v_addi (getr R' 10) (bv_signed (0%bv : bv 12)) = Z_to_bv 64 (o2 + 32)).
  { rewrite G10. change (bv_signed (0%bv : bv 12)) with 0. rewrite v_addi_Z by lia. f_equal; lia. }
  pose proof (fp_step_flw (PropExec.mkFP F fc) asegs R' (Z_to_bv 64 NT_FLW) M1 (seg_rom asegs) W_eada8 15%bv 10%bv 0%bv
                (Z_to_bv 64 (o2 + 32)) _ F_eada8 eq_refl D_eada8 A10 RD) as S1.
