  assert (S2 : RiscvSemantics.step asegs (@PropExec.mkst (PropExec.mkFP F1 fc) R' (Z_to_bv 64 (NT_FLW + 4)) M1 (seg_rom asegs))
             = MachineOk (@PropExec.mkst (PropExec.mkFP F1 fc) R' (Z_to_bv 64 NT_FSW) M1 (seg_rom asegs))).
