  replace (NT_FSW + 4) with NT_T4 in S3 by (unfold NT_FSW, NT_T4; lia).
  rewrite ADR in S3.
  lazymatch type of S3 with _ = MachineOk (@PropExec.mkst _ _ _ ?mm _) => change mm with M2 in S3 end.
  assert (HmsT : CatSim.msteps asegs (MS R F (Z_to_bv 64 NT_T2) fc None m (seg_rom asegs))
