  assert (MI2 : mem_inv asegs M2) by exact (msteps_mem_inv asegs _ _ HmsT MI).
  assert (INL : forall b, In b (LB0 ++ LBs2) -> In b LB) by (intros b Hb; exact (Permutation_in _ (Permutation_sym PE) Hb)).
  assert (TS2 : TSN s LB bl2 bc2 ents2 LBs2 M2).
  { eapply TSN_hdr; [exact HTS | exact MU2 | exact WM2 | exact MI2 | exact INL | exact UB1 | exact UB2 | exact UB3 | exact UB4 | exact UB5]. }
  rewrite G2, G8, G9, G10, G11, G12, G13, G14, G18, G19, G20, G21, G22, G23, G24 in HRe.
