  Definition ntl2_LH : Z := 0xed074.
  Definition ntl2_srL : list expr := srs sr_id
    [(11%bv, EVar 35); (12%bv, EVar 32); (13%bv, EVar 33); (14%bv, EVar 34); (15%bv, EVar 36); (22%bv, ELit SHBASE)].
  Definition ntl2_KL : list kentry :=
    [ KWr (SA (EAlu ALU_ADD (EVar 32) (EVar 33)) 0) (ELit 8);
      KRange (EVar 32) 1 (2 ^ 47); KRange (EVar 33) 0 (2 ^ 44); KRange (EVar 34) 0 (2 ^ 40); KRange (EVar 35) 1 (2 ^ 40);
