  Lemma ntl2_wsub : forall a b, 0 <= b <= a -> a < 2 ^ 64 ->
    alu64 ALU_SUB (Z_to_bv 64 a) (Z_to_bv 64 b) = Z_to_bv 64 (a - b).
  Proof.
    intros a b Hb Ha. apply bv_eq. cbn [alu64 alu].
    rewrite bv_sub_unsigned, !Z_to_bv_unsigned, !bv_wrap64_mod.
    rewrite (Z.mod_small a), (Z.mod_small b), !Z.mod_small by lia. reflexivity.
  Qed.

  Lemma ntl2_dsh : forall a b A n, (b <= SHBASE \/ AHI_LO <= a) -> 0 <= A -> 0 <= n -> A + n <= 2 ^ 47 ->
    disjoint_from [(a, b)] (sh A) (nsh n).
  Proof.
    intros a b A n Hlh HA Hn HAn. cbn [disjoint_from]. split; [|exact I].
    pose proof (sh_nsh_high A n HA Hn ltac:(unfold AAPP_HI; lia)) as Hs.
    assert (ASHADOW_BASE <= sh A) by (unfold sh; pose proof (Z.div_pos A 8 HA ltac:(lia)); lia).
    pose proof ASHADOW_BASE_val as HB. unfold SHBASE in Hlh. lia.
  Qed.

