      (x1 x5 x6 x7 x10 x16 x17 x25 x26 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (msF : machine_state) (mo : Model) (m : mem) (s : as_St H),
    Z.of_nat n = bc1 - i ->
