                             (Z_to_bv 64 bc1) (Z_to_bv 64 bl1) (Z_to_bv 64 (8 * i)) (Z_to_bv 64 i) (Z_to_bv 64 (2 ^ 64 - 1 - bl1)) x16 x17
                             (rO o1 16) (Z_to_bv 64 o1) (rO o1 8) (rO o1 24) (Z_to_bv 64 SHBASE) (rSh (rO o1 24)) (rSrl o1)
                             x25 x26 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 ntl2_LH) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) ->
