    intros W m m' o bl bc fst sz mlf pad Hh MU WM DJ. unfold hdr40 in *.
    eapply rw_cells_transport; [exact Hh | exact MU | exact WM | exact DJ].
  Qed.

  Lemma ntl2_negm1 : forall a, 0 <= a < 2 ^ 64 ->
    alu64 ALU_ADD (mul_div M_MUL (Z_to_bv 64 (-1)) (Z_to_bv 64 a)) (Z_to_bv 64 (-1)) = Z_to_bv 64 (2 ^ 64 - 1 - a).
