    intros a Ha. apply bv_eq. cbn [alu64 alu mul_div].
    rewrite bv_add_unsigned, bv_mul_unsigned, !Z_to_bv_unsigned, !bv_wrap64_mod.
    rewrite <- Z.mul_mod by lia. rewrite <- Z.add_mod by lia.
    replace (2 ^ 64 - 1 - a) with (-1 * a + -1 + 1 * 2 ^ 64) by lia. rewrite Z.mod_add by lia. reflexivity.
  Qed.

