  Lemma ntm_l2 : forall (bl1 bc1 bl2 bc2 : Z) (wf1 wz1 : word) (ents2 : list (Z * (Z * (Z * Z * Z)))) (LB LBs2 : list block) (qb1 : bptr) (junk1 : list byte)
