                        F (Z_to_bv 64 NT_L2) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    TSN s LB bl2 bc2 ents2 LBs2 m ->
