    assert (P16' : rw_cells asegs M1 (o1 + 16) [C8 (Z_to_bv 64 0)]) by (unfold M1, LG; rwc_new Hlf (proj2 P16)).
    assert (HD1' := hdr40_join M1 o1 _ _ _ _ _ _ ltac:(unfold M1, LG; rwc_keep P0 Hlf) ltac:(unfold M1, LG; rwc_keep P8 Hlf)
                      P16' ltac:(unfold M1, LG; rwc_keep P24 Hlf) ltac:(unfold M1, LG; rwc_keep P32 Hlf) ltac:(unfold M1, LG; rwc_keep P36 Hlf)).
    pose proof (ntl2_hdr_tr _ _ _ _ _ _ _ _ _ _ HD2 MU1 WM1 ltac:(cbn [disjoint_from]; split; [lia | exact I])) as HD2'.
    assert (ADM1 : addressable M1 bl1 (8 * bc1)).
    { eapply addressable_transport; [exact J3 | exact MU1 | exact WM1 | apply ntl2_dsh; lia]. }
    assert (WR1 : wr_at asegs M1 bl1 (8 * bc1)) by exact (wr_at_wmono _ _ _ _ (own_of_rw_cells _ _ _ _ J2 ltac:(lia)) WM1).
    readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
    rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 11%bv G11. rreg HR' 12%bv G12. rreg HR' 13%bv G13. rreg HR' 14%bv G14.
    rreg HR' 15%bv G15. rreg HR' 18%bv G18. rreg HR' 19%bv G19. rreg HR' 20%bv G20. rreg HR' 21%bv G21. rreg HR' 22%bv G22.
    rreg HR' 23%bv G23. rreg HR' 24%bv G24.
    rewrite w_addm in G8 by lia. replace (o1 + -88) with st1 in G8 by lia.
    rewrite ntl2_negm1 in G15 by lia.
    rewrite G2, G8, G11, G12, G13, G14, G15, G18, G19, G20, G21, G22, G23, G24 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1. rewrite HRe in VIS1. clear HRe.
    eapply (ntl2_loop (Z.to_nat bc1) _ 0 bl1 bc1); [rewrite Z2Nat.id by lia; lia | exact VIS1 | exact KR1 | lia | lia | lia | exact Hb8 | lia
      | exact Hba | exact WR1 | exact ADM1 | exact MI1 |].
    intros msF2 mo2 M2 y10 y11 y12 y13 y14 y15 y16 y17 y25 VIS2 KR2 MP2 MU2 WM2 MI2.
    assert (PE2 : Permutation LB ((LB0 ++ LBs2) ++ [(qb1, bl1, 8 * bc1)])).
    { rewrite (proj2 (Z.eqb_neq bc1 0) Hz) in PE.
      eapply Permutation_trans; [exact PE|]. rewrite <- app_assoc. apply Permutation_app_head. apply Permutation_app_comm. }
    assert (TS2 : TSN s LB bl2 bc2 ents2 LBs2 M2).
    { eapply (TSN_munchB s LB bl2 bc2 ents2 LBs2 M1 M2 [(bl1, bl1 + 8 * bc1)] qb1 bl1 (8 * bc1));
        [exact TS1 | exact MU2 | exact WM2 | exact MI2 | apply Forall_cons; [right; cbn [fst snd]; lia | apply Forall_nil] | exact PE2
        | exact UB1 | exact UB2 | exact UB3 | exact UB4 | exact UB5]. }
    pose proof (ntl2_hdr_tr _ _ _ _ _ _ _ _ _ _ HD1' MU2 WM2 ltac:(cbn [disjoint_from]; split; [lia | exact I])) as HD1''.
    pose proof (ntl2_hdr_tr _ _ _ _ _ _ _ _ _ _ HD2' MU2 WM2 ltac:(cbn [disjoint_from]; split; [lia | exact I])) as HD2''.
    assert (ADM2 : addressable M2 bl1 (8 * bc1)).
    { eapply addressable_transport; [exact ADM1 | exact MU2 | exact WM2 | apply ntl2_dsh; lia]. }
    pose proof TS2 as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & OWN2).
    destruct (rw_cells_of_own LB M2 (qb1, bl1, 8 * bc1) OWN2 INb ltac:(cbn; exact HqI) ltac:(cbn; lia)) as (bs & CBS).
    unfold blk_addr, blk_size in CBS. cbn [fst snd] in CBS.
    eapply ntm_l2m with (s := s) (msF := msF2) (mo := mo2) (m := M2) (junk1 := bs).
    + exact VIS2.
    + exact KR2.
    + eapply (ah_mpres_trans H HH); [exact MP | eapply (ah_mpres_trans H HH); [exact MP1 | exact MP2]].
    + exact TS2.
    + exact PE.
    + exact AL.
    + exact HD1''.
    + exact HD2''.
    + exact B0.
    + intros _. split; [exact J0|]. split; [exact J1|]. split; [exact CBS | exact ADM2].
    + exact U2.
    + exact PM2.
    + exact AP2.
Qed.

  Fixpoint nodes_okAN (LBn : list block) (m : mem) (ns : list (Z * list byte)) : Prop :=
    match LBn, ns with
    | [], [] => True
    | b :: LBn', (q, tl) :: ns' =>
        blk_addr b = q /\ blk_size b = 32
        /\ rw_cells asegs m q [C8 (Z_to_bv 64 (match ns' with [] => 0 | (q', _) :: _ => q' end)); CB 24 tl]
        /\ addressable m q 32
        /\ (match ns' with [] => True | (q', _) :: _ => 0x6e8000 <= q' < 2 ^ 47 end)
        /\ nodes_okAN LBn' m ns'
    | _, _ => False
    end.

