  Lemma ntm_loop : forall (ns : list (Z * list byte)) (q : Z) (tl : list byte) (b0 : block) (LBn : list block)
      (bl1 bc1 bl2 bc2 : Z) (wf1 wz1 : word) (ents2 : list (Z * (Z * (Z * Z * Z)))) (LB LBs2 : list block) (qb1 : bptr) (junk1 : list byte)
      (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x26 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (msF : machine_state) (mo : Model) (m : mem) (s : as_St H) (pad1 pad2 : list byte),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 (spz - 96)) gp tp x5 x6 x7 (Z_to_bv 64 st1) (Z_to_bv 64 st2) (Z_to_bv 64 q) x11 x12 x13 x14 x15 x16 x17
                             (rO o1 16) (Z_to_bv 64 o1) (rO o1 8) (rO o1 24) (Z_to_bv 64 2147450880) (rSh (rO o1 24)) (rSrl o1)
                             (rSh (rO o1 16)) x26 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 NT_LOOP) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    TSN s LB bl2 bc2 ents2 LBs2 m ->
    Permutation LB ((LB0 ++ (if bc1 =? 0 then [] else [(qb1, bl1, 8 * bc1)])) ++ b0 :: LBn ++ LBs2) -> as_AL H s >= as_AL H st0 ->
    nodes_okAN (b0 :: LBn) m ((q, tl) :: ns) ->
    hdr40 m o1 (Z_to_bv 64 bl1) (Z_to_bv 64 bc1) wf1 wz1 (Z_to_bv 64 0x3f800000) pad1 ->
    hdr40 m o2 (Z_to_bv 64 bl2) (Z_to_bv 64 bc2) (Z_to_bv 64 (hdaddr ents2)) (Z_to_bv 64 (Zlength ents2)) (Z_to_bv 64 0x3f800000) pad2 ->
    (bc1 = 0 -> bl1 = 0) ->
    (bc1 <> 0 -> 0 < bl1 /\ 0 < bc1 <= 26339969 /\ rw_cells asegs m bl1 [CB (Z.to_nat (8 * bc1)) junk1] /\ addressable m bl1 (8 * bc1)) ->
    umapx MI_A 32 (nval32 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ents2 ->
    Permutation (lbl LBs2) (umap_blocks 32 bl2 bc2 ents2) ->
    (forall b, In b LBs2 -> apart o1 40 (blk_addr b) (blk_size b)) ->
