  Lemma nodes_existN : forall (ents : list (Z * (Z * (Z * Z * Z)))) (LBn : list block) (m : mem),
    lbl LBn = map (fun e => (fst e, 32)) ents ->
    HRep.chain ASEGS m ents -> lb_own LBn m ->
    (forall p k v, In (p, (k, v)) ents -> addressable m p 32 /\ AIMG_TOP <= p /\ p + 32 <= 2 ^ 47) ->
