  Lemma ntloop_bkt : forall (Ak : list block) (bl bc : Z), lbl Ak = (if bc =? 0 then [] else [(bl, 8 * bc)]) ->
    (bc = 0 /\ Ak = []) \/ (bc <> 0 /\ exists qb, Ak = [(qb, bl, 8 * bc)]).
  Proof.
    intros Ak bl bc E. destruct (Z.eqb_spec bc 0) as [Z0|NZ].
    - left. split; [exact Z0|]. destruct Ak; [reflexivity | discriminate E].
    - right. split; [exact NZ|]. destruct Ak as [|[[qb a] n] Ak']; [discriminate E|].
      unfold lbl in E. cbn [map fst snd] in E. injection E as Ea En Er.
      destruct Ak'; [|discriminate Er]. exists qb. rewrite Ea, En. reflexivity.
  Qed.

  Lemma ntloop_umapx_live : forall (l l' : list (Z * Z)) M o bl bc (ents : list (Z * (Z * (Z * Z * Z)))),
    umapx MI_A 32 (nval32 ASEGS) l M o bl bc ents ->
    (forall x, In x (umap_blocks 32 bl bc ents) -> In x l') ->
    umapx MI_A 32 (nval32 ASEGS) l' M o bl bc ents.
  Proof.
    intros l l' M o bl bc ents U INC.
    destruct U as [HD Hal Hlo Hhi Hbs Hld Hbl Hbal Hbllo Hblhi Hblobj Hbkt Hnd Hch Hnode Hap].
    constructor; try assumption.
    - destruct Hbl as [K|[K1 K2]]; [left; exact K | right; split; [exact K1|]].
      change (In (bl, 8 * bc) l'). apply INC. unfold umap_blocks. apply in_or_app. left.
      destruct (Z.eqb_spec bc 0); [contradiction | left; reflexivity].
    - intros p k v Hin. destruct (Hnode p k v Hin) as (_ & R). split; [|exact R].
      change (In (p, 32) l'). apply INC. unfold umap_blocks. apply in_or_app. right.
      apply in_map_iff. exists (p, (k, v)). split; [reflexivity | exact Hin].
  Qed.

  Lemma ntloop_perm_tail : forall (LB L0 L1 L2 Mb Mn : list block),
    Permutation LB (L0 ++ L1 ++ L2) -> Permutation L1 (Mb ++ Mn) -> Permutation LB ((L0 ++ Mb) ++ Mn ++ L2).
  Proof.
    intros LB L0 L1 L2 Mb Mn P1 P2. rewrite <- app_assoc. eapply Permutation_trans; [exact P1|].
    apply Permutation_app_head. rewrite app_assoc. apply Permutation_app_tail. exact P2.
  Qed.
  Lemma ntm_entry : forall (bl1 bc1 bl2 bc2 : Z) (ents1 ents2 : list (Z * (Z * (Z * Z * Z)))) (LB LBs1 LBs2 : list block)
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (msF : machine_state),
    as_VIS H st0 msF = MS (mkR x1 (Z_to_bv 64 (spz - 96)) gp tp x5 x6 x7 (Z_to_bv 64 st1) (Z_to_bv 64 st2) x10 x11 x12 x13
                              x14 x15 x16 x17 x18 x19 x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 NT_E) fc None m0 (seg_rom asegs) ->
    as_AKREL H st0 (mkCfg msF mo0) ->
    TSN st0 LB bl2 bc2 ents2 LBs2 m0 ->
    umapx MI_A 32 (nval32 ASEGS) (lbl LB) m0 o1 bl1 bc1 ents1 -> umap_sh m0 32 (bl1, bc1, ents1) ->
    umapx MI_A 32 (nval32 ASEGS) (lbl LB) m0 o2 bl2 bc2 ents2 ->
    Permutation LB (LB0 ++ LBs1 ++ LBs2) ->
    Permutation (lbl LBs1) (umap_blocks 32 bl1 bc1 ents1) -> Permutation (lbl LBs2) (umap_blocks 32 bl2 bc2 ents2) ->
    (forall b, In b LBs2 -> apart o1 40 (blk_addr b) (blk_size b)) ->
    as_SR H (ntm_post bl2 bc2 ents2 LBs2) (mkCfg msF mo0).
Proof using All.
  intros bl1 bc1 bl2 bc2 ents1 ents2 LB LBs1 LBs2 x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26
    x28 x29 x30 x31 F msF VIS KR TS U1 SH1 U2 PE P1 P2 AP2.
  pose proof TS as (MI & ST & ERR & RA & AC & RF & S0 & RH & FR & AD1 & AD2 & USH & XP & OWN).
  pose proof (aceil_facts) as ((ACF1 & ACF2) & ACF3 & ACF4).
  pose proof O1R as (O1a & O1b & O1c & O1d). pose proof O2R as (O2a & O2b & O2c & O2d & O2e).
  pose proof O1a as O1u. pose proof O2a as O2u. unfold AIMG_TOP in O1u, O2u.
  assert (GZ1 : gz m0 o1 40) by (intros i Hi; eapply sh0_of_addressable; [exact AD1 | change (8 * (40 / 8)) with 40; lia]).
  destruct (hdr40_of_hdrN _ _ _ _ _ (u_hdr U1) O1a ltac:(lia)) as (pad1 & HD1).
  destruct (hdr40_of_hdrN _ _ _ _ _ (u_hdr U2) O2a ltac:(lia)) as (pad2 & HD2).
  pose proof U1 as [_ _ _ _ UBS ULD UBL UBA UBLO UBHI _ _ _ UCH UND _].
  pose proof (BSEQ_boundT bc1 UBS) as BSB.
  pose proof SH1 as [SHb SHn]. unfold HStmts.t3a, HStmts.t3b, HStmts.t3c in SHb, SHn. cbn [fst snd] in SHb, SHn.
  pose proof (ntloop_umapx_live _ _ _ _ _ _ _ U2 (fun x Hx => Permutation_in _ (Permutation_sym P2) Hx)) as U2'.
  unfold umap_blocks in P1.
  destruct (lbl_perm_split LBs1 _ _ P1) as (Mb & Mn & PM & Eb & En).
  assert (INs1 : forall b, In b LBs1 -> In b LB)
    by (intros b Hb; apply (Permutation_in _ (Permutation_sym PE)); apply in_or_app; right; apply in_or_app; left; exact Hb).
  assert (INb : forall b, In b Mb -> In b LB)
    by (intros b Hb; apply INs1; apply (Permutation_in _ (Permutation_sym PM)); apply in_or_app; left; exact Hb).
  assert (INn : forall b, In b Mn -> In b LB)
    by (intros b Hb; apply INs1; apply (Permutation_in _ (Permutation_sym PM)); apply in_or_app; right; exact Hb).
  assert (MBQ : exists qb, Mb = (if bc1 =? 0 then [] else [(qb, bl1, 8 * bc1)])
     /\ (bc1 <> 0 -> exists jk, rw_cells asegs m0 bl1 [CB (Z.to_nat (8 * bc1)) jk])).
  { destruct (ntloop_bkt Mb bl1 bc1 Eb) as [(Z0 & EM)|(NZ & qb & EM)].
    - exists 0. rewrite EM. destruct (Z.eqb_spec bc1 0); [|contradiction]. split; [reflexivity | intros C; contradiction].
    - exists qb. rewrite EM. destruct (Z.eqb_spec bc1 0); [contradiction|]. split; [reflexivity|]. intros _.
      assert (INq : In (qb, bl1, 8 * bc1) LB) by (apply INb; rewrite EM; left; reflexivity).
      pose proof (ah_blocks H HH _ _ _ _ RH INq) as (_ & _ & _ & Q3 & _). unfold blk_addr, blk_size in Q3. cbn [fst snd] in Q3.
      pose proof (rw_cells_of_own LB m0 _ OWN INq) as RO. unfold blk_addr, blk_size in RO. cbn [fst snd] in RO.
      apply RO; [exact Q3 | lia]. }
  destruct MBQ as (qb1 & EMb & JKx).
  assert (JK : exists jk, bc1 <> 0 -> rw_cells asegs m0 bl1 [CB (Z.to_nat (8 * bc1)) jk]).
  { destruct (Z.eq_dec bc1 0) as [Z0|NZ]; [exists []; intros C; contradiction|].
    destruct (JKx NZ) as (jk & J). exists jk. intros _. exact J. }
  destruct JK as (junk1 & JK).
  assert (BZ : bc1 = 0 -> bl1 = 0) by (intros Z0; destruct UBL as [[_ K]|[K _]]; [exact K | contradiction]).
  assert (BNZ : bc1 <> 0 -> 0 < bl1 /\ 0 < bc1 <= 26339969 /\ rw_cells asegs m0 bl1 [CB (Z.to_nat (8 * bc1)) junk1]
                            /\ addressable m0 bl1 (8 * bc1)).
  { intros NZ. split; [exact (UBLO NZ)|]. split; [lia|]. split; [exact (JK NZ)|]. exact (SHb NZ). }
  pose proof (hdr40_split _ _ _ _ _ _ _ _ HD1) as (P0 & P8 & P16 & P24 & P32 & P36).
  lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
  destruct ents1 as [|[p0 [k0 v0]] ents1'].
  - destruct Mn as [|bx Mn']; [|unfold lbl in En; cbn [map] in En; discriminate En].
    pose (E := Eseed R [Z_to_bv 64 o1; Z_to_bv 64 0]).
    assert (HR : regs_ok E (srs sr_id [(8%bv, EAlu ALU_ADD (EVar 32) (ELit (-88))); (22%bv, ELit 2147450880)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; try reflexivity; wfix. }
    assert (HK : know_ok asegs E m0 (kn_fix 30 [NT_L1; NT_L2; NT_LOOP] (SCR [] [] []) NT_E
        (srs sr_id [(8%bv, EAlu ALU_ADD (EVar 32) (ELit (-88))); (22%bv, ELit 2147450880)])
        [ KRange (EVar 32) 0x6e8000 (2 ^ 47); KAlign (EVar 32) 8; KWord (SA (EVar 32) 24) 8 (EVar 33); KRange (EVar 33) 0 0 ] 40)).
    { kn_eval. unfold know_ok.
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. lia. }
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. split; [lia | exact O1c]. }
      apply Forall_cons. { eapply (kword_of_rw_cells asegs _ _ _ _ 0%nat); [exact P24 | reflexivity | reflexivity | lia | rwc_norm | lia | cbn; lia | reflexivity]. }
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. lia. }
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R NT_E m0 (seg_rom asegs) HR HK 40%nat [NT_L1; NT_L2; NT_LOOP] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1; try sc_shdj; try sc_dj. }
    assert (FHF : rfull R) by (rewrite HR0; apply rfull_mkR).
    readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
    rreg HR' 8%bv G8. rreg HR' 10%bv G10. rreg HR' 18%bv G18. rreg HR' 19%bv G19. rreg HR' 20%bv G20.
    rreg HR' 21%bv G21. rreg HR' 22%bv G22. rreg HR' 23%bv G23. rreg HR' 24%bv G24.
    rewrite G8, G10, G18, G19, G20, G21, G22, G23, G24 in HRe.
    assert (W8 : alu64 ALU_ADD (Z_to_bv 64 o1) (Z_to_bv 64 (-88)) = Z_to_bv 64 st1) by wfix.
    rewrite W8 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1. rewrite HRe in VIS1. clear HRe.
    eapply ntm_t1 with (bl1 := bl1) (bc1 := bc1) (qb1 := qb1) (junk1 := junk1) (pad1 := pad1) (pad2 := pad2) (LB := LB)
      (LBs2 := LBs2) (s := st0) (msF := msF1) (mo := mo1) (m := m0).
    + exact VIS1.
    + exact KR1.
    + exact MP1.
    + exact TS.
    + pose proof (ntloop_perm_tail _ _ _ _ _ _ PE PM) as PP. rewrite EMb in PP. cbn [app] in PP. rewrite <- app_assoc in PP. exact PP.
    + lia.
    + exact HD1.
    + exact HD2.
    + exact BZ.
    + exact BNZ.
    + exact U2'.
    + exact P2.
    + exact AP2.
  - assert (NF : forall p k v, In (p, (k, v)) ((p0, (k0, v0)) :: ents1') -> addressable m0 p 32 /\ AIMG_TOP <= p /\ p + 32 <= 2 ^ 47).
    { intros p k v Hin. split; [exact (SHn p k v Hin)|].
      destruct (UND p k v Hin) as (_ & _ & PH & _).
      assert (Hl : In (p, 32) (lbl Mn)) by (rewrite En; apply in_map_iff; exists (p, (k, v)); split; [reflexivity | exact Hin]).
      apply lbl_in_inv in Hl. destruct Hl as (q & Hq).
      pose proof (ah_blocks H HH _ _ _ _ RH (INn _ Hq)) as (_ & _ & _ & Q3 & _).
      unfold blk_addr, blk_size in Q3. cbn [fst snd] in Q3. split; [exact Q3 | lia]. }
    destruct (nodes_existN _ Mn m0 En UCH (lb_own_incl LB Mn m0 INn OWN) NF) as (ns & NO & FS).
    destruct ns as [|[q tl] ns']; [discriminate FS|]. cbn [map fst] in FS. injection FS as Fq _. subst q.
    destruct Mn as [|b0 LBn]; [cbn [nodes_okAN] in NO; contradiction|].
    destruct (NF p0 k0 v0 (or_introl eq_refl)) as (_ & NP0a & NP0b). pose proof NP0a as NP0u. unfold AIMG_TOP in NP0u.
    assert (ZL : 1 <= Zlength ((p0, (k0, v0)) :: ents1') <= bc1).
    { split; [unfold HRep.Zlength; cbn [length]; lia | exact ULD]. }
    pose (E := Eseed R [Z_to_bv 64 o1; Z_to_bv 64 (Zlength ((p0, (k0, v0)) :: ents1')); Z_to_bv 64 p0]).
    assert (HR : regs_ok E (srs sr_id [(8%bv, EAlu ALU_ADD (EVar 32) (ELit (-88))); (22%bv, ELit 2147450880)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; try reflexivity; wfix. }
    assert (HK : know_ok asegs E m0 (kn_fix 30 [NT_L1; NT_L2; NT_LOOP] (SCR [] [] []) NT_E
        (srs sr_id [(8%bv, EAlu ALU_ADD (EVar 32) (ELit (-88))); (22%bv, ELit 2147450880)])
        [ KRange (EVar 32) 0x6e8000 (2 ^ 47); KAlign (EVar 32) 8; KWord (SA (EVar 32) 24) 8 (EVar 33); KRange (EVar 33) 1 (2 ^ 63);
          KWord (SA (EVar 32) 16) 8 (EVar 34); KRange (EVar 34) 1 (2 ^ 47) ] 40)).
    { kn_eval. unfold know_ok.
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. lia. }
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. split; [lia | exact O1c]. }
      apply Forall_cons. { eapply (kword_of_rw_cells asegs _ _ _ _ 0%nat); [exact P24 | reflexivity | reflexivity | lia | rwc_norm | lia | cbn; lia | reflexivity]. }
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. lia. }
      apply Forall_cons. { eapply (kword_of_rw_cells asegs _ _ _ _ 0%nat); [exact P16 | reflexivity | reflexivity | lia | rwc_norm | lia | cbn; lia | reflexivity]. }
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. lia. }
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R NT_E m0 (seg_rom asegs) HR HK 40%nat [NT_L1; NT_L2; NT_LOOP] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1; try sc_shdj; try sc_dj. }
    assert (FHF : rfull R) by (rewrite HR0; apply rfull_mkR).
    readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
    rreg HR' 8%bv G8. rreg HR' 10%bv G10. rreg HR' 18%bv G18. rreg HR' 19%bv G19. rreg HR' 20%bv G20.
    rreg HR' 21%bv G21. rreg HR' 22%bv G22. rreg HR' 23%bv G23. rreg HR' 24%bv G24. rreg HR' 25%bv G25.
    rewrite G8, G10, G18, G19, G20, G21, G22, G23, G24, G25 in HRe.
    assert (W8 : alu64 ALU_ADD (Z_to_bv 64 o1) (Z_to_bv 64 (-88)) = Z_to_bv 64 st1) by wfix.
    rewrite W8 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1. rewrite HRe in VIS1. clear HRe.
    eapply ntm_loop with (ns := ns') (q := p0) (tl := tl) (b0 := b0) (LBn := LBn) (bl1 := bl1) (bc1 := bc1) (qb1 := qb1)
      (junk1 := junk1) (pad1 := pad1) (pad2 := pad2) (LB := LB) (LBs2 := LBs2) (s := st0) (msF := msF1) (mo := mo1) (m := m0).
    + exact VIS1.
    + exact KR1.
    + exact MP1.
    + exact TS.
    + pose proof (ntloop_perm_tail _ _ _ _ _ _ PE PM) as PP. rewrite EMb in PP. exact PP.
    + lia.
    + exact NO.
    + exact HD1.
    + exact HD2.
    + exact BZ.
    + exact BNZ.
    + exact U2'.
    + exact P2.
    + exact AP2.
Qed.

